function applyRadioTrack(track){
  const player=document.querySelector("#party-radio-player");
  if(!player||!track?.mediaUrl)return;
  player.volume=radioVolume;
  if(player.src!==track.mediaUrl){
    player.src=track.mediaUrl;
    const seek=()=>{if(track.elapsedSeconds>0)player.currentTime=track.elapsedSeconds;player.removeEventListener("loadedmetadata",seek);};
    player.addEventListener("loadedmetadata",seek);
    player.play().catch(()=>{});
  }
}
function stopRadioVisualizer(){cancelAnimationFrame(radioAnimationId);radioAnimationId=null;radioSourceElement=null;}
function setupRadioVisualizer(){
  const canvas=document.querySelector("#party-radio-canvas"),audio=document.querySelector("#party-radio-player");
  if(!canvas||!audio){stopRadioVisualizer();return;}
  audio.volume=radioVolume;
  if(radioSourceElement===audio)return;
  try{
    radioAudioCtx??=new (window.AudioContext||window.webkitAudioContext)();
    if(radioAudioCtx.state==="suspended")radioAudioCtx.resume().catch(()=>{});
    const source=radioAudioCtx.createMediaElementSource(audio);
    radioAnalyser=radioAudioCtx.createAnalyser();
    radioAnalyser.fftSize=64;
    source.connect(radioAnalyser);
    radioAnalyser.connect(radioAudioCtx.destination);
    radioSourceElement=audio;
    const data=new Uint8Array(radioAnalyser.frequencyBinCount),ctx2d=canvas.getContext("2d");
    cancelAnimationFrame(radioAnimationId);
    const draw=()=>{
      if(!document.body.contains(canvas)){stopRadioVisualizer();return;}
      radioAnimationId=requestAnimationFrame(draw);
      radioAnalyser.getByteFrequencyData(data);
      ctx2d.clearRect(0,0,canvas.width,canvas.height);
      const barWidth=canvas.width/data.length;
      for(let i=0;i<data.length;i++){const barHeight=(data[i]/255)*canvas.height;ctx2d.fillStyle="rgba(255,255,255,0.75)";ctx2d.fillRect(i*barWidth,canvas.height-barHeight,barWidth-2,barHeight);}
    };
    draw();
  }catch{}
}
function spawnRadioReaction(reaction){
  const host=document.querySelector("#party-radio-reactions");
  if(!host)return;
  const emojis={like:"👍",heart:"❤️",fire:"🔥",clap:"👏"},node=document.createElement("span");
  node.textContent=emojis[reaction]||"👍";
  node.style.cssText=`position:absolute;left:${10+Math.random()*80}%;bottom:0;font-size:22px;animation:party-reaction-float 1.6s ease-out forwards`;
  host.append(node);
  setTimeout(()=>node.remove(),1600);
}
function updateRadioMediaSession(track){
  if(!("mediaSession" in navigator))return;
  if(!track){navigator.mediaSession.metadata=null;navigator.mediaSession.playbackState="none";return;}
  navigator.mediaSession.metadata=new MediaMetadata({title:track.title||"Radio",artist:track.artistName||"SunoTo Radio",artwork:track.artworkUrl?[{src:track.artworkUrl,sizes:"512x512"}]:[]});
  navigator.mediaSession.playbackState="playing";
  navigator.mediaSession.setActionHandler("play",()=>document.querySelector("#party-radio-player")?.play().catch(()=>{}));
  navigator.mediaSession.setActionHandler("pause",()=>document.querySelector("#party-radio-player")?.pause());
  navigator.mediaSession.setActionHandler("nexttrack",()=>partyClient?.send("RADIO_SKIP_VOTE",{}));
}
function leavePartyRoom(){stopPartyClient();partyMessages=[];state.partyRoom=null;state.partyQueueTracks=[];state.partyNowPlaying="";state.partyVideoParticipants=[];state.partyLocalVideoOn=false;state.partyMembers=[];state.partyMode="chat";state.partyCurrentTrack=null;state.partyRadioVotes={skipVotes:0,replayVotes:0,totalMembers:1};state.partySeated=false;state.partyIsCoHost=false;state.partySeatLimit=10;state.partySeatedCount=0;state.partySeatRequests=[];updateRadioMediaSession(null);render();}
function handlePartyEvent(type,payload){
  if(type==="READY"){state.partyMembers=(payload.members||[]).map(member=>member.participantId).filter(id=>id&&id!==payload.participantId);if(payload.mode)state.partyMode=payload.mode;state.partyCurrentTrack=payload.currentTrack||null;state.partySeated=Boolean(payload.seated);state.partyIsCoHost=Boolean(payload.isCoHost);state.partySeatLimit=payload.seatLimit||10;state.partySeatedCount=payload.seatedCount||0;applyRadioTrack(payload.currentTrack);updateRadioMediaSession(payload.currentTrack||null);refreshRadioQueueSidebar();render();}
  if(type==="ROOM_MODE_CHANGED"){state.partyMode=payload.mode;render();}
  if(type==="RADIO_TRACK_CHANGED"||type==="RADIO_TRACK_REPLAY"){state.partyCurrentTrack=payload.track;state.partyRadioVotes={skipVotes:0,replayVotes:0,totalMembers:state.partyRadioVotes?.totalMembers||1};applyRadioTrack(payload.track);updateRadioMediaSession(payload.track);if(type==="RADIO_TRACK_CHANGED")refreshRadioQueueSidebar();render();}
  if(type==="RADIO_QUEUE_EMPTY"){state.partyCurrentTrack=null;updateRadioMediaSession(null);render();}
  if(type==="RADIO_VOTE_UPDATE"){state.partyRadioVotes={skipVotes:payload.skipVotes,replayVotes:payload.replayVotes,totalMembers:payload.totalMembers};const skipButton=document.querySelector("#party-radio-skip"),replayButton=document.querySelector("#party-radio-replay");if(skipButton)skipButton.textContent=`Skip (${payload.skipVotes}/${payload.totalMembers})`;if(replayButton)replayButton.textContent=`Once more (${payload.replayVotes}/${payload.totalMembers})`;}
  if(type==="ROOM_MESSAGE")appendPartyMessage("peer",String(payload.text||""));
  if(type==="MEMBER_JOINED"){appendPartyMessage("system",`Someone joined (${String(payload.participantId||"").slice(0,8)})`);if(payload.participantId&&!state.partyMembers.includes(payload.participantId)){state.partyMembers=[...state.partyMembers,payload.participantId];render();}if(partyClient?.isHost&&partyClient.hostStream&&payload.participantId)partyClient.offerToListener(payload.participantId).catch(()=>{});}
  if(type==="MEMBER_LEFT"){appendPartyMessage("system",`Someone left (${String(payload.participantId||"").slice(0,8)})`);state.partyMembers=state.partyMembers.filter(id=>id!==payload.participantId);if(payload.participantId&&state.partyVideoParticipants.includes(payload.participantId)){state.partyVideoParticipants=state.partyVideoParticipants.filter(id=>id!==payload.participantId);}render();}
  if(type==="PARTY_VIDEO_TRACK"){if(!state.partyVideoParticipants.includes(payload.participantId)){state.partyVideoParticipants=[...state.partyVideoParticipants,payload.participantId];render();}const el=document.querySelector(`[data-party-video="${payload.participantId}"]`);if(el)el.srcObject=payload.stream;}
  if(type==="REPORT_ACCEPTED"){state.partyMessage=payload.message||"Report received.";render();}
  if(type==="MESSAGE_REJECTED"&&payload.code==="report_failed"){state.partyMessage="Could not send the report. Try again.";render();}
  if(type==="PLAYBACK_SYNC"){state.partyNowPlaying=String(payload.track||"");render();}
  if(type==="HOST_INACTIVE"){state.partyMessage="The host went inactive. Anyone can claim host from the room.";render();}
  if(type==="ROOM_CLOSED"){state.partyMessage="This room was closed.";leavePartyRoom();}
  if(type==="SESSION_REPLACED"){state.partyMessage="You started listening in another tab or device, so playback stopped here.";leavePartyRoom();}
  if(type==="SEAT_REQUESTED"){if(payload.participantId&&!state.partySeatRequests.includes(payload.participantId)){state.partySeatRequests=[...state.partySeatRequests,payload.participantId];render();}}
  if(type==="SEAT_GRANTED"){state.partySeated=true;state.partyMessage="You have been given a seat.";render();}
  if(type==="SEAT_DENIED"){state.partyMessage="Your seat request was denied.";render();}
  if(type==="SEAT_REVOKED"){state.partySeated=false;state.partyMessage="Your seat was revoked.";render();}
  if(type==="MEMBER_SEATED"){state.partySeatedCount=Math.min(state.partySeatLimit,state.partySeatedCount+1);state.partySeatRequests=state.partySeatRequests.filter(id=>id!==payload.participantId);render();}
  if(type==="MEMBER_UNSEATED"){state.partySeatedCount=Math.max(0,state.partySeatedCount-1);render();}
  if(type==="MEMBER_BANNED"){appendPartyMessage("system",`A member was banned (${String(payload.participantId||"").slice(0,8)})`);render();}
  if(type==="BANNED"){state.partyMessage="You were banned from this room.";leavePartyRoom();}
  if(type==="COHOST_APPOINTED"){state.partyIsCoHost=true;state.partyMessage="You are now a co-host.";render();}
  if(type==="COHOST_REVOKED"){state.partyIsCoHost=false;state.partyMessage="Your co-host status was revoked.";render();}
  if(type==="MEMBER_COHOST_CHANGED"){appendPartyMessage("system",`${payload.isCoHost?"Co-host appointed":"Co-host revoked"} (${String(payload.participantId||"").slice(0,8)})`);render();}
  if(type==="PREAUTHORIZE_ACCEPTED"){state.partyMessage="User pre-authorized for a seat.";render();}
  if(type==="MESSAGE_REJECTED"&&payload.code==="room_full"){state.partyMessage="The room is full — no seats available.";render();}
  if(type==="MESSAGE_REJECTED"&&payload.code==="cohost_requires_premium"){state.partyMessage="Co-hosts must have a premium membership.";render();}
  if(type==="MESSAGE_REJECTED"&&payload.code==="preauthorize_requires_premium"){state.partyMessage="Pre-authorized users must have a premium membership.";render();}
  if(type==="RADIO_REACTION")spawnRadioReaction(payload.reaction);
}
