function handleRealtimeEvent(event){const payload=event.payload||{};if(event.type==="MESSAGE_RECEIVED")appendMessage("peer",String(payload.text||""));if(event.type==="MESSAGE_ACCEPTED"){const text=pendingMessages.get(event.eventId);if(text){appendMessage("me",text);pendingMessages.delete(event.eventId);}}if(event.type==="MESSAGE_REJECTED"||event.type==="RATE_LIMITED"){pendingMessages.delete(event.eventId);chatNotice(payload.message||payload.code||payload.reason||"Message was not accepted.");}if(event.type==="MATCH_COOLDOWN"){nextRequested=false;chatNotice(`You can find someone new in ${payload.remainingSeconds||1} seconds.`);}if(event.type==="TIMER_STATE"){if(Number.isFinite(payload.remainingSeconds)){const timer=document.querySelector("#chat-timer"),seconds=Math.max(0,payload.remainingSeconds);if(timer)timer.textContent=`${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`;}if(payload.idleWarning)chatNotice(payload.message||"Still there? Tap to stay available.",[["Stay available","ACTIVITY"]]);if(payload.idle===true)chatNotice("You were marked idle. Tap or type to become active again.",[["I'm here","ACTIVITY"]]);}if(event.type==="PEER_IDLE")chatNotice("The other person is idle. You can wait or choose Next.");if(event.type==="PEER_TYPING"){const indicator=document.querySelector("#peer-typing");if(indicator)indicator.hidden=!payload.typing;}if(event.type==="PEER_STREAMING_STATUS"&&payload.recording){const banner=document.querySelector("#peer-recording-banner");if(banner)banner.hidden=false;}if(event.type==="CONTINUE_REQUESTED")chatNotice(`Both people must accept to continue. Each delivered message costs ${payload.messageCredits||10} Credits.`,[["Continue","CONTINUE_ACCEPT"],["End","CONTINUE_DECLINE"]]);if(event.type==="CONTINUE_ACTIVATED"){chatNotice("Paid continuation is active.");enablePaidPhotoUI();}if(event.type==="PHOTO_RECEIVED")showDisappearingPhoto(payload.data,payload.durationSeconds);if(event.type==="PAYMENT_HOLD")chatNotice("Chat is paused because a payment could not be completed.");if(event.type==="CONTACT_UNLOCK_REQUEST")chatNotice(`The other person wants to unlock contact sharing for ${payload.costEach||500} Credits each.`,[["Accept","CONTACT_UNLOCK_ACCEPT"],["Decline","CONTACT_UNLOCK_DECLINE"]]);if(event.type==="CONTACT_UNLOCKED")chatNotice(`Contact sharing is unlocked for ${payload.seconds||300} seconds.`);if(event.type==="CONTACT_UNLOCK_ENDED")chatNotice("Contact sharing is locked again.");if(event.type==="LIKE_ACCEPTED")chatNotice("Like sent privately.");if(event.type==="LIKE_RECEIVED")chatNotice("They liked this chat 👍");if(event.type==="REPORT_ACCEPTED")chatNotice("Report received. This chat is ending.");if(event.type==="BLOCK_ACCEPTED")chatNotice("Blocked. This chat is ending.");if(event.type==="PEER_DISCONNECTED")chatNotice("The other person disconnected. Waiting briefly for them to return…");if(event.type==="PEER_RETURNED")chatNotice("");if(event.type==="SESSION_ENDED"){const destination=nextRequested?"searching":"history";nextRequested=false;finishChat(payload.reason,destination,false).catch(()=>{});}
if(event.type==="VIDEO_ELIGIBLE"){state.videoEligible=true;const panel=document.querySelector("#video-panel");if(panel)panel.hidden=false;if(payload.initiator)startVideoCall();}
if(event.type==="VIDEO_OFFER"){if(!videoCall){const panel=document.querySelector("#video-panel");if(panel)panel.hidden=false;videoCall=new VideoCallClient({send:(type,sendPayload)=>realtime?.send(type,sendPayload),onLocalStream:stream=>{const el=document.querySelector("#video-local");if(el)el.srcObject=stream;},onRemoteStream:stream=>{const el=document.querySelector("#video-remote");if(el)el.srcObject=stream;},onEnded:()=>stopVideoCall(false)});}videoCall.handleSignal("VIDEO_OFFER",payload).catch(error=>{chatNotice(error.message||"Could not start video.");stopVideoCall(false);});}
if(event.type==="VIDEO_ANSWER")videoCall?.handleSignal("VIDEO_ANSWER",payload).catch(()=>{});
if(event.type==="VIDEO_ICE_CANDIDATE")videoCall?.handleSignal("VIDEO_ICE_CANDIDATE",payload).catch(()=>{});
if(event.type==="VIDEO_END")stopVideoCall(false);
}
function monitorChatActivity(){activityCleanup?.();let lastSent=0;const signal=()=>{const now=Date.now();if(routeName()!=="chat"||now-lastSent<10000)return;if(realtime?.send("ACTIVITY"))lastSent=now;};const events=["pointerdown","touchstart","keydown","focus"];for(const type of events)window.addEventListener(type,signal,{passive:true});const visibility=()=>{if(document.visibilityState==="visible")signal();};document.addEventListener("visibilitychange",visibility);activityCleanup=()=>{for(const type of events)window.removeEventListener(type,signal);document.removeEventListener("visibilitychange",visibility);activityCleanup=null;};}
async function loadAuth(){return authModule??=await import("./auth.js")}
async function loadAccountApi(){return(accountApiModule??=await import("./account-api.js")).accountApi}
async function loadRazorpay(){if(window.Razorpay)return window.Razorpay;await new Promise((resolve,reject)=>{const script=document.createElement("script");script.src="https://checkout.razorpay.com/v1/checkout.js";script.onload=resolve;script.onerror=()=>reject(new Error("Could not load secure checkout"));document.head.append(script);});return window.Razorpay;}
async function refreshAccount(session,message=""){state.accountSession=session;state.accountMessage=message;state.accountProfile=null;state.wallet=null;state.walletLedger=[];state.streamingMembershipActive=false;if(session){try{const accountApi=await loadAccountApi();const [profile,wallet,ledger,streaming]=await Promise.all([accountApi.profile(session),accountApi.wallet(session),accountApi.ledger(session),accountApi.streamingMembershipStatus(session).catch(()=>({active:false}))]);state.accountProfile=profile;state.wallet=wallet.wallet;state.walletLedger=ledger.entries;state.streamingMembershipActive=Boolean(streaming.active);let deviceId=localStorage.getItem("random-chat.account-device.v1");if(!deviceId){deviceId=crypto.randomUUID();localStorage.setItem("random-chat.account-device.v1",deviceId);}await accountApi.claimDevice(session,deviceId);}catch(error){state.accountMessage=error.message;}}if(routeName()==="account")render();}
async function ensureAccountAuth(){if(!accountInitialization)accountInitialization=(async()=>{const auth=await loadAuth();auth.onAuthChange((session,event)=>{if(event==="PASSWORD_RECOVERY")state.passwordRecovery=true;refreshAccount(session);});await refreshAccount(await auth.currentSession());})();try{return await accountInitialization}catch(error){accountInitialization=null;throw error}}
async function accountAction(action,success){try{state.accountMessage="Working…";render();await action();state.accountMessage=success;}catch(error){state.accountMessage=error.message;}render();}
async function gamesAction(action,success){try{state.gamesMessage="Working…";render();await action();if(success!=null)state.gamesMessage=success;}catch(error){state.gamesMessage=error.message;}render();}
function mountMatchPreferences(){const form=document.querySelector("#onboarding-form");if(!form||document.querySelector("#match-preferences"))return;const section=document.createElement("fieldset");section.id="match-preferences";section.className="field full match-preferences";const legend=document.createElement("legend");legend.textContent="Optional matching preferences · paid only on an exact match";section.append(legend);const field=(label,name,element)=>{const wrapper=document.createElement("label");wrapper.className="field";const caption=document.createElement("span");caption.textContent=label;element.name=name;wrapper.append(caption,element);section.append(wrapper);return element;},select=(placeholder,values)=>{const node=document.createElement("select"),first=document.createElement("option");first.value="";first.textContent=placeholder;node.append(first);for(const value of values){const option=document.createElement("option");option.value=value;option.textContent=value;node.append(option);}return node;};field("Gender","targetGender",select("Any gender",["Male","Female","Other"]));const min=field("Minimum age","ageMin",document.createElement("input")),max=field("Maximum age","ageMax",document.createElement("input"));for(const input of [min,max]){input.type="number";input.min="18";input.max="100";input.placeholder="Any";}field("Language","targetLanguage",select("Any language",LANGUAGES));field("Radius","radiusKm",select("Any distance",APP_CONFIG.radiusOptionsKm.map(value=>String(value))));const common=document.createElement("label");common.className="preference-check";const checkbox=document.createElement("input");checkbox.type="checkbox";checkbox.name="commonInterest";const commonText=document.createElement("span");commonText.textContent="Require at least one common interest";common.append(checkbox,commonText);section.append(common);const price=document.createElement("small");price.id="preference-price";price.className="muted";section.append(price);const update=()=>{try{const value=readMatchPreferences(form,false),fee=preferenceFee(value);price.textContent=fee?`Exact mutual match: ${fee} Credits. Full 30/45-second human search; random fallback costs 0.`:"Random matching has no preference fee.";}catch{price.textContent="Choose gender and a complete age range before using radius.";}};section.addEventListener("input",update);form.querySelector('label input[type="checkbox"][required]')?.closest("label")?.before(section);update();}
function readMatchPreferences(form,validate=true){const data=new FormData(form),gender=String(data.get("targetGender")||"")||null,ageMin=data.get("ageMin")?Number(data.get("ageMin")):null,ageMax=data.get("ageMax")?Number(data.get("ageMax")):null,language=String(data.get("targetLanguage")||""),radiusKm=data.get("radiusKm")?Number(data.get("radiusKm")):null,value={gender,ageMin,ageMax,language,commonInterest:data.get("commonInterest")==="on",radiusKm};if(validate){const genderInput=form.elements.targetGender;if((ageMin!==null||ageMax!==null)&&!gender){genderInput.setCustomValidity("Choose a gender when using an age preference.");genderInput.reportValidity();throw new Error("invalid_match_preferences");}if(ageMin!==null&&ageMax!==null&&ageMin>ageMax){form.elements.ageMax.setCustomValidity("Maximum age must not be lower than minimum age.");form.elements.ageMax.reportValidity();throw new Error("invalid_match_preferences");}if(radiusKm!==null&&(!gender||ageMin===null||ageMax===null)){genderInput.setCustomValidity("Radius requires gender and a complete age range.");genderInput.reportValidity();throw new Error("invalid_match_preferences");}}return value;}
